const { marco, T, flecha, ficha, pasos, compara, rejilla, ciclo, barras, bloque, formula, B, M, A, q4, V, mapaB, figura, PROFE, FUENTE_RD, PAU, uid } = require("./_bach2-ti");

// Neurona artificial: entradas, pesos, suma, función de activación y salida.
const neuronaSVG = (() => {
  const id = uid("nr");
  const fl = (d, c = "var(--ink)") => `<path d="${d}" fill="none" stroke="${c}" stroke-width="1.6" marker-end="url(#${id})"/>`;
  const ent = (y, x, w) => `<circle cx="30" cy="${y}" r="13" fill="var(--card)" stroke="var(--leaf)" stroke-width="2"/>${T(30, y + 4, x, { fs: 10.5, b: true, c: "var(--leaf)" })}${fl(`M43 ${y} L 112 ${88 + (y - 88) * 0.25}`)}${T(76, y + (y < 88 ? -6 : y > 88 ? 14 : -6), w, { fs: 10, b: true, c: "var(--red)" })}`;
  return marco("Neurona artificial: cada entrada x se multiplica por su peso w, se suman junto con el sesgo b y el resultado pasa por una función de activación que da la salida y", `
  ${ent(40, "x₁", "w₁")}${ent(88, "x₂", "w₂")}${ent(136, "x₃", "w₃")}
  <circle cx="130" cy="88" r="20" fill="var(--card)" stroke="var(--pen)" stroke-width="2.2"/>${T(130, 94, "Σ", { fs: 16, b: true, c: "var(--pen)" })}
  ${fl("M130 40 V 66", "var(--muted)")}${T(130, 32, "sesgo b", { fs: 9.5, c: "var(--muted)" })}
  ${fl("M150 88 H 172")}<rect x="172" y="72" width="34" height="32" rx="6" fill="var(--card)" stroke="var(--red)" stroke-width="2"/><path d="M178 98 C 188 98, 190 78, 200 78" fill="none" stroke="var(--red)" stroke-width="1.8"/>
  ${fl("M206 88 H 236")}${T(246, 92, "y", { fs: 12, b: true, c: "var(--leaf)" })}
  ${T(189, 120, "activación", { fs: 9.5, c: "var(--muted)" })}${T(130, 166, "y = f(w₁x₁ + w₂x₂ + w₃x₃ + b)", { fs: 11, b: true })}`, flecha(id, "var(--ink)"));
})();

